/**
 * Market Data Vendor Instruments of the Volatility Surfaces
 *
 * Installs the ids the contributors of the latent FX volatility surfaces quote, in each
 * contributor's own notation, and maps each to the fx_option item of its point, which is the item
 * the surface blueprints' pillars read. It runs after the surfaces are staged
 * (synthetic_feeds_bloomberg_volatility_populate.sql), and reads them: a point is one row for each
 * expiry of each surface, each label the feed quotes, and each contributor that quotes it.
 *
 * No id is written by hand. tools/vendor_catalogue writes the block between the markers below,
 * from the query in the header of marketdata_vendor_instruments_populate.sql: it calls each
 * contributor's notation to write each id, the datum codec for each item, and reads every id back.
 *
 * This script is idempotent.
 */

\echo '--- Market Data Vendor Instruments of the Volatility Surfaces ---'

do $$
declare
    v_stale text;
begin
create temporary table t_fx_option_id (
    provider_code text, base_currency_code text, quote_currency_code text, expiry text,
    strike_label text, id_scheme text, external_id text, field text, oresmd_uri text
) on commit drop;

-- BEGIN GENERATED fx option ids: tools/vendor_catalogue writes this block, see the header
    -- bloomberg: 910 with an id, 0 without
