-- The points the staged surfaces quote: one row for each contributor, surface, expiry and label.
create temporary table t_fx_option_point (
    provider_code text, base_currency_code text, quote_currency_code text, expiry text,
    strike_label text
) on commit drop;

insert into t_fx_option_point
select distinct c.provider_code, f.base_currency_code, f.quote_currency_code, e.tenor, l.label
from ores_dq_fx_vol_surface_feeds_artefact_tbl f
join ores_dq_fx_vol_surface_feed_expiries_artefact_tbl e
  on e.dataset_id = f.dataset_id and e.feed_id = f.id
join ores_dq_fx_vol_surface_feed_contributors_artefact_tbl k
  on k.dataset_id = f.dataset_id and k.feed_id = f.id
join ores_dq_fx_vol_contributors_artefact_tbl c
  on c.dataset_id = k.dataset_id and c.id = k.contributor_id
cross join (values ('ATM'), ('25RR'), ('25BF'), ('10RR'), ('10BF')) as l (label)
where f.enabled;

-- A point no row above names is one this seed cannot write; the ids are generated, so the fix is
-- to regenerate them.
select string_agg(distinct p.provider_code || ' ' || p.base_currency_code || '/' ||
                  p.quote_currency_code || ' ' || p.expiry, '; ')
into v_stale
from t_fx_option_point p
where not exists (
    select 1 from t_fx_option_id i
    where i.provider_code = p.provider_code
      and i.base_currency_code = p.base_currency_code
      and i.quote_currency_code = p.quote_currency_code
      and i.expiry = p.expiry
      and i.strike_label = p.strike_label
);

if v_stale is not null then
    raise exception 'The surfaces quote points the volatility seed has no id for: %. Regenerate the seed: see the header of marketdata_vendor_instruments_populate.sql.', v_stale;
end if;

insert into ores_marketdata_market_data_vendor_instruments_tbl (
    id, tenant_id, version, provider_code, id_scheme, external_id, field, minted, deviation_note,
    modified_by, performed_by, change_reason_code, change_commentary
)
select distinct md5(i.provider_code || '|' || i.id_scheme || '|' || i.external_id || '|' || i.field)::uuid,
       ores_utility_system_tenant_id_fn(), 0, i.provider_code, i.id_scheme, i.external_id, i.field,
       false, '', current_user, current_user, 'system.initial_load',
       'Initial population of the FX volatility vendor instruments'
from t_fx_option_point p
join t_fx_option_id i
  on i.provider_code = p.provider_code
 and i.base_currency_code = p.base_currency_code
 and i.quote_currency_code = p.quote_currency_code
 and i.expiry = p.expiry
 and i.strike_label = p.strike_label
where i.external_id is not null
  and not exists (
    select 1 from ores_marketdata_market_data_vendor_instruments_tbl v
    where v.tenant_id = ores_utility_system_tenant_id_fn()
      and v.provider_code = i.provider_code
      and v.id_scheme = i.id_scheme
      and v.external_id = i.external_id
      and v.field = i.field
      and v.valid_to = ores_utility_infinity_timestamp_fn()
);

insert into ores_marketdata_market_data_mappings_tbl (
    id, tenant_id, version, vendor_instrument_id, oresmd_uri, effective_from,
    modified_by, performed_by, change_reason_code, change_commentary
)
select gen_random_uuid(), ores_utility_system_tenant_id_fn(), 0, v.id, i.oresmd_uri,
       timestamptz '2026-01-01 00:00:00+00', current_user, current_user, 'system.initial_load',
       'Initial population of the FX volatility mappings'
from t_fx_option_id i
join ores_marketdata_market_data_vendor_instruments_tbl v
  on v.tenant_id = ores_utility_system_tenant_id_fn()
 and v.provider_code = i.provider_code
 and v.id_scheme = i.id_scheme
 and v.external_id = i.external_id
 and v.field = i.field
 and v.valid_to = ores_utility_infinity_timestamp_fn()
where i.external_id is not null
  and not exists (
    select 1 from ores_marketdata_market_data_mappings_tbl m
    where m.tenant_id = ores_utility_system_tenant_id_fn()
      and m.vendor_instrument_id = v.id
      and m.valid_to = ores_utility_infinity_timestamp_fn()
);
end $$;
